(()=>{function sync(){if(typeof dashboard==='undefined'||!dashboard?.company)return false;window.dashboard=dashboard;const roles=dashboard.company.capabilities||[],isContractor=roles.includes('contractor'),isSubcontractor=roles.includes('subcontractor'),subcontractorOnly=isSubcontractor&&!isContractor,role=isContractor&&isSubcontractor?'Contractor & Subcontractor':isContractor?'Contractor':'Subcontractor',profileTitle=isContractor&&isSubcontractor?'Contractor & Subcontractor Profile':isContractor?'Contractor Profile':'Subcontractor Profile';const badge=document.getElementById('navRole'),profileNav=document.querySelector('[data-view="profile"]'),jobsNav=document.querySelector('[data-view="jobs"]'),postForm=document.getElementById('jobPostForm'),postedJobs=document.getElementById('postedJobsSection'),jobsHeading=document.querySelector('#jobsView>.page-heading');if(badge)badge.textContent=role;if(profileNav)profileNav.textContent=profileTitle;let postDialog=document.getElementById('contractorPostJobDialog'),postButton=document.getElementById('contractorPostJobButton');if(!postDialog&&postForm){postDialog=document.createElement('dialog');postDialog.id='contractorPostJobDialog';postDialog.className='modal job-post-modal';postDialog.innerHTML='<button class="modal-close" type="button" aria-label="Close post job form">&times;</button>';postDialog.appendChild(postForm);document.body.appendChild(postDialog);postDialog.querySelector('.modal-close').onclick=()=>postDialog.close()}if(!postButton&&jobsHeading){postButton=document.createElement('button');postButton.id='contractorPostJobButton';postButton.className='button button-orange';postButton.type='button';postButton.textContent='Post a Job';postButton.onclick=()=>postDialog?.showModal();jobsHeading.appendChild(postButton)}if(postButton)postButton.hidden=!isContractor;if(isContractor){if(postForm){postForm.hidden=false;postForm.style.display='';postForm.removeAttribute('aria-hidden');postForm.querySelectorAll('input,textarea,button,select').forEach(field=>field.disabled=false)}if(postedJobs&&jobsHeading&&postedJobs.previousElementSibling!==jobsHeading)jobsHeading.after(postedJobs)}if(subcontractorOnly){if(jobsNav)jobsNav.childNodes[0].textContent='Find Jobs ';[postForm,postedJobs].forEach(element=>{if(!element)return;element.hidden=true;element.style.display='none';element.setAttribute('aria-hidden','true')});postForm?.querySelectorAll('input,textarea,button,select').forEach(field=>field.disabled=true)}return true}if(!sync()){const timer=setInterval(()=>{if(sync())clearInterval(timer)},100);setTimeout(()=>clearInterval(timer),20000)}})();
