(()=>{const paths={overview:'/dashboard',jobs:'/jobs',messages:'/messages',network:'/network',profile:'/profile',calendar:'/calendar',notifications:'/notifications'},views=Object.fromEntries(Object.entries(paths).map(([view,path])=>[path,view])),originalSwitchView=switchView,overviewButton=document.querySelector('[data-view="overview"]'),header=document.querySelector('.dashboard-header');if(overviewButton)overviewButton.textContent='Dashboard';switchView=function(name,historyMode='push'){originalSwitchView(name);if(header)header.hidden=name!=='overview';document.title=`${name==='overview'?'Dashboard':name[0].toUpperCase()+name.slice(1)} | Trades`;const path=paths[name]||paths.overview;if(historyMode==='push'&&location.pathname!==path)history.pushState({view:name},'',path);if(historyMode==='replace'&&location.pathname!==path)history.replaceState({view:name},'',path)};window.addEventListener('popstate',()=>switchView(views[location.pathname]||'overview','none'));switchView(views[location.pathname]||'overview','replace')})();
